tests.script:
// Save access & refresh tokens to environment (supports Postman pm or Thunder Client client APIs)
try {
  const res = (typeof pm !== 'undefined' && pm.response) ? pm.response.json() : (typeof responseBody !== 'undefined' ? JSON.parse(responseBody) : null);
  if (res) {
    try { pm.environment.set('accessToken', res.access); pm.environment.set('refreshToken', res.refresh); } catch(e) { /* not Postman */ }
    try { client && client.setEnvironment && client.setEnvironment('accessToken', res.access); client && client.setEnvironment && client.setEnvironment('refreshToken', res.refresh); } catch(e) { /* not Thunder */ }
  }
} catch(e) { /* ignore */ }

preRequest.script:
try {
  var token = '';
  try { token = (typeof pm !== 'undefined' && pm.environment) ? pm.environment.get('accessToken') : ''; } catch(e) {}
  try { if (!token && typeof client !== 'undefined' && client.getEnvironment) token = client.getEnvironment('accessToken'); } catch(e) {}
  if (token) {
    try { if (typeof pm !== 'undefined' && pm.request && pm.request.headers) pm.request.headers.upsert({key: 'Authorization', value: 'Bearer ' + token}); } catch(e) {}
    try { if (typeof client !== 'undefined' && client.setRequest) client.setRequest({ headers: [{key: 'Authorization', value: 'Bearer ' + token}] }); } catch(e) {}
  }
} catch(e) {}

